$$

$$
\frac {\partial \boldsymbol {z} ^ {(l + 1)}}{\partial \boldsymbol {a} ^ {(l)}} = (\boldsymbol {W} ^ {(l + 1)}) ^ {\top} \quad \in \mathbb {R} ^ {M _ {l} \times M _ {l + 1}}. \tag {4.57}
