$$
\left[ \frac {\partial \mathcal {L} (\boldsymbol {y} , \hat {\boldsymbol {y}})}{\partial \boldsymbol {W} ^ {(l)}} \right] _ {i j} = \left[ \delta^ {(l)} (\boldsymbol {a} ^ {(l - 1)}) ^ {\top} \right] _ {i j}. \tag {4.67}
